mapper.select:
SELECT w.id, w.buyer_id AS buyerId, u.username AS buyerName, u.buyer_rating_score AS buyerRatingScore, w.title, w.author, w.category_id AS categoryId, w.budget, w.desired_condition AS desiredCondition, w.expected_location AS expectedLocation, w.description, w.status, w.created_at AS createdAt, 1 AS isOwner FROM wanted_request w LEFT JOIN user u ON w.buyer_id = u.id WHERE w.deleted_at IS NULL AND w.buyer_id = #{buyerId}
AND ( w.title LIKE CONCAT('%', #{query.keyword}, '%') OR w.author LIKE CONCAT('%', #{query.keyword}, '%') OR w.description LIKE CONCAT('%', #{query.keyword}, '%') )
AND w.status = #{query.status}
ORDER BY w.created_at DESC

mapper.update:
UPDATE wanted_request
SET deleted_at = NOW(),
    updated_at = NOW()
WHERE id = #{id}
  AND buyer_id = #{buyerId}
  AND deleted_at IS NULL
